    async function loadWoNiu4KVerify() {
      const result = await api('/website/api/woniu4k/verify');
      woniu4kTaskId = result.data && result.data.taskId ? result.data.taskId : '';
      const box = $('woniu4kVerifyBox');
      if (box) box.innerHTML = '<img src="' + escapeHtml(result.data.image || '') + '" alt="\u9A8C\u8BC1\u7801" style="height:42px;max-width:160px;background:#fff;border-radius:6px;padding:4px">';
      const input = $('woniu4kVerify');
      if (input) input.value = '';
      toast('\u9A8C\u8BC1\u7801\u5DF2\u83B7\u53D6');
    }
    async function loginWoNiu4K() {
      if (!woniu4kTaskId) {
        await loadWoNiu4KVerify();
        setMessage('\u9A8C\u8BC1\u7801\u5DF2\u663E\u793A\uFF0C\u8BF7\u8F93\u5165\u9A8C\u8BC1\u7801\u540E\u518D\u70B9\u767B\u5F55\u4FDD\u5B58\u3002');
        return;
      }
      await api('/website/api/woniu4k/login',{method:'PUT',body:JSON.stringify({account:$('woniu4kAccount').value,password:$('woniu4kPassword').value,verify:$('woniu4kVerify').value,taskId:woniu4kTaskId})});
      woniu4kTaskId = '';
      toast('\u8717\u725B I 4K \u5DF2\u767B\u5F55');
      await refresh();
    }
